// Seeded random number generators.
//
// JavaRandom is a bit-exact port of java.util.Random (48-bit LCG), so that a
// board generated in JavaScript with seed N is identical to one generated by the
// original Java applet with `new Random(N)`. This is what makes "golden" tests
// against the original program possible.
//
// All engine code must obtain randomness through an object with this interface:
//   rng.nextInt(bound)  -> integer in [0, bound)
//   rng.next()          -> float in [0, 1)

const MULT = 0x5DEECE66Dn;
const ADD = 0xBn;
const MASK = (1n << 48n) - 1n;

export class JavaRandom {
  constructor(seed = Date.now()) {
    this.setSeed(seed);
  }

  setSeed(seed) {
    // Accept anything a URL or a test script may hand us: strings, floats,
    // NaN, Infinity. Non-finite values fall back to the clock; fractions are
    // truncated like Java's (long) cast would.
    let n = typeof seed === 'bigint' ? seed : Number(seed);
    if (typeof n !== 'bigint') n = Number.isFinite(n) ? BigInt(Math.trunc(n)) : BigInt(Date.now());
    this.seed = (n ^ MULT) & MASK;
  }

  // Equivalent of java.util.Random.next(bits), returns a signed 32-bit int.
  nextBits(bits) {
    this.seed = (this.seed * MULT + ADD) & MASK;
    const r = Number(this.seed >> BigInt(48 - bits));
    // Java's (int) cast: keep low 32 bits as signed.
    return r | 0;
  }

  // Equivalent of java.util.Random.nextInt(bound).
  nextInt(bound) {
    if (!(bound > 0)) throw new RangeError('bound must be positive');
    if ((bound & -bound) === bound) {
      // power of two
      return Number((BigInt(bound) * BigInt(this.nextBits(31))) >> 31n);
    }
    let bits;
    let val;
    do {
      bits = this.nextBits(31);
      val = bits % bound;
    } while (((bits - val + (bound - 1)) | 0) < 0);
    return val;
  }

  next() {
    return this.nextInt(1 << 30) / (1 << 30);
  }
}

// Small, fast, non-Java PRNG; handy for stress tests where speed matters.
export class Mulberry32 {
  constructor(seed = 1) {
    this.a = seed >>> 0;
  }

  next() {
    let t = (this.a += 0x6D2B79F5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  nextInt(bound) {
    return Math.floor(this.next() * bound);
  }
}

export function createRng(seed) {
  return new JavaRandom(seed);
}
